INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63893437', 63893437, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Penyusunan KLHS dan Raperpres RTR KSN TN Sembilang', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 268532000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Kawasan Strategis Nasional (KSN) adalah wilayah yang penataan ruangnya diprioritaskan karena mempunyai pengaruh sangat penting secara nasional terhadap kedaulatan negara, pertahanan dan keamanan negara, ekonomi, sosial, budaya, dan/atau lingkungan, termasuk wilayah yang telah ditetapkan sebagai warisan dunia. Penataan ruang KSN dilakukan untuk mengembangkan, melestarikan, melindungi dan/atau mengkoordinasikan keterpaduan pembangunan nilai strategis kawasan dalam mendukung penataan ruang wilayah. Dalam Pasal 14 Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang sebagaimana beberapa kali telah diubah terakhir dalam Undang-Undang Nomor 6 Tahun 2023 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 2 Tahun 2022 tentang Cipta Kerja menjadi Undang-Undang, dinyatakan bahwa Rencana Tata Ruang (RTR) Pulau/Kepulauan dan Rencana Tata Ruang (RTR) Kawasan Strategis Nasional (KSN) merupakan rencana rinci yang disusun sebagai perangkat operasional dari rencana umum tata ruang pada sistem nasional. Selanjutnya PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang RTRWN menetapkan 76 (tujuh puluh enam) KSN. Dalam Lampiran X PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang RTRWN, disebutkan bahwa KSN Kawasan Taman Nasional Sembilang merupakan KSN dari sudut kepentingan Lingkungan Hidup, dengan penekanan pada sisi pelestarian keanekaragaman hayati, rehabilitasi/revitalisasi kawasan dan pengurangan emisi karbon. Sebagai salah satu pemangku kepentingan (stakeholder) pembangunan di pemerintahan, Direktorat Jenderal Tata Ruang, Kementerian Agraria dan Tata Ruang/Badan Pertanahan Nasional, memiliki tugas merumuskan serta melaksanakan kebijakan di bidang penataan ruang dengan tujuan mencapai hasil (outcome) berupa terlaksananya pengaturan, perencanaan tata ruang, pemanfaatan ruang, dan pengembangan Kawasan Strategis Nasional, serta terselenggaranya pembinaan perencanaan tata ruang dan pemanfaatan ruang daerah. Oleh karena itu, dalam rangka melaksanakan amanat RTRWN terhadap penyusunan Perpres Kawasan Strategis Nasional (KSN) Kawasan Taman Nasional Sembilang, dalam tahun anggaran 2026 Direktorat Perencanaan Tata Ruang Nasional-Direktorat Jenderal Tata Ruang melaksanakan kegiatan Fasilitasi Legislasi RPepres RTR KSN Kawasan Taman Nasional Sembilang.', 'KELUARAN Dokumen RPepres tentang RTR KSN Kawasan Taman Nasional Sembilang yang telah disepakati muatannya oleh K/L dan Pemerintah Daerah; Data spasial (Album Peta) format digital dengan format *.shp skala 1:50.000; Surat permohonan pengusulan ke dalam Program Penyusunan Peraturan Presiden dari Menteri ATR/BPN ke Menteri Hukum dan HAM; Selain dokumen tersebut, kegiatan ini juga menghasilkan dokumen laporan yang terdiri dari: Laporan Pendahuluan Laporan Pendahuluan, dibuat sebanyak 4 (empat) eksemplar dan dalam bentuk softcopy format *.doc (word) berukuran kertas minimal A4 serta Pdf file. Laporan ini sekurang-kurangnya berisi metoda pelaksanaan masing-masing aktivitas yang tercakup dalam ruang lingkup kegiatan, jadwal pelaksanaan kegiatan secara lebih terinci, Surat Keputusan tentang Pembentukan Tim Swakelola, dan agenda pelaksanaan pekerjaan. Laporan pendahuluan diserahkan selambat-lambatnya 30 (tiga puluh) hari terhitung sejak tanggal dimulainya pekerjaan dalam SK Tim Swakelola. Laporan Bulanan Laporan Bulanan, dibuat sebanyak 4 (empat) eksemplar dan dalam bentuk softcopy format *.doc (word) berukuran kertas A4 serta Pdf file yang berisi seluruh kegiatan yang dilaksanakan per bulan. Laporan Akhir Laporan akhir, dibuat sebanyak 4 (empat) eksemplar dan dalam bentuk softcopy format *.doc (word) berukuran kertas A4 serta Pdf file yang berisi seluruh kegiatan yang dilaksanakan dalam kegiatan ini. Laporan ini memuat rangkuman dan hasil-hasil kegiatan selama Tahun Anggaran 2026 disertai dengan review dan evaluasi pelaksanaannya (dalam ruang lingkup yang sesuai dengan tugas-tugas kesekretariatan). Laporan akhir diserahkan pada akhir masa pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1207755);
